use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: failed to read stdin: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => String::from_utf8(b).map_err(|_| format!("error: {}: stream did not contain valid UTF-8", path)),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet, src);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    icon::validate(&b.nodes, b.sheet, file, opts).map_err(|e| (e, vec![]))?;
    b.resolve_links().map_err(|e| (e, vec![]))?;
    page::root_fixup(&mut b.nodes, b.sheet);
    b.unworn_class_warnings();
    let nodes = std::mem::take(&mut b.nodes);
    let links = std::mem::take(&mut b.links);
    let mut warnings = std::mem::take(&mut b.warnings);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links,
        warnings: std::mem::take(&mut warnings),
        root_font_size: 15.0,
        sk: Default::default(),
        link_geo: vec![],
    };
    compile::compute(&mut ctx);
    if drawing::expand(&mut ctx).map_err(|e| (e, vec![]))? {
        compile::compute(&mut ctx);
    }
    chart::validate(&ctx).map_err(|e| (e, vec![]))?;
    page::scale_units(&mut ctx);
    drawing::prepare(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    image::check_sizes(&ctx).map_err(|e| (e, vec![]))?;
    layout::measure(&mut ctx, 0, None);
    drawing::size_warnings(&mut ctx);
    links::compute(&mut ctx);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    table::check_grids(&ctx).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}
// Command-line parsing, mirroring clap's behaviour and messages.

pub static HELP_MAIN: &str = include_str!("../data/help/main.txt");
pub static HELP_FMT: &str = include_str!("../data/help/fmt.txt");
pub static HELP_SERVE: &str = include_str!("../data/help/serve.txt");
pub static HELP_DESUGAR: &str = include_str!("../data/help/desugar.txt");
pub static HELP_HIGHLIGHT: &str = include_str!("../data/help/highlight.txt");
pub static HELP_THEME: &str = include_str!("../data/help/theme.txt");
pub static HELP_HELP: &str = include_str!("../data/help/help.txt");
pub static HIGHLIGHT_CSS: &str = include_str!("../data/help/highlight.css");

pub enum Cmd {
    Compile { input: String },
    Fmt { input: String, check: bool, stdout: bool },
    Serve,
    Desugar { input: String },
    Highlight { input: Option<String>, css: bool },
    Theme { name: Option<String> },
}

pub struct Parsed {
    pub cmd: Cmd,
    pub opts: crate::Options,
}

pub enum Outcome {
    Run(Parsed),
    Print(String), // help / version text on stdout, exit 0
    Fail(String),  // error text on stderr, exit 3
}

struct OptDef {
    long: &'static str,
    short: Option<char>,
    value: Option<&'static str>, // value name when the option takes one
}

const MAIN_OPTS: &[OptDef] = &[
    OptDef { long: "output", short: Some('o'), value: Some("OUTPUT") },
    OptDef { long: "format", short: None, value: Some("FORMAT") },
    OptDef { long: "static", short: None, value: None },
    OptDef { long: "embed-font", short: None, value: None },
    OptDef { long: "check", short: None, value: None },
    OptDef { long: "json", short: None, value: None },
    OptDef { long: "theme", short: None, value: Some("NAME|FILE|A/B") },
    OptDef { long: "watch", short: None, value: None },
    OptDef { long: "no-fs", short: None, value: None },
    OptDef { long: "no-warn", short: None, value: None },
    OptDef { long: "strict", short: None, value: None },
    OptDef { long: "help", short: Some('h'), value: None },
    OptDef { long: "version", short: Some('V'), value: None },
];

const SUBCOMMANDS: &[&str] = &["fmt", "serve", "desugar", "highlight", "theme", "help"];

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut am = vec![false; a.len()];
    let mut bm = vec![false; b.len()];
    let mut m = 0usize;
    for i in 0..a.len() {
        let lo = i.saturating_sub(range);
        let hi = (i + range + 1).min(b.len());
        for j in lo..hi {
            if !bm[j] && a[i] == b[j] {
                am[i] = true;
                bm[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if am[i] {
            while !bm[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = m as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64 / 2.0) / m) / 3.0
}

fn suggest(given: &str, cands: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for c in cands {
        let s = jaro(given, c);
        if s > 0.7 && best.map(|b| s > b.0).unwrap_or(true) {
            best = Some((s, c));
        }
    }
    best.map(|b| b.1.to_string())
}

pub fn sub_help(bin: &str, text: &str) -> String {
    text.replace("{bin}", bin)
}

fn generic_usage(bin: &str) -> String {
    format!("Usage: {} [OPTIONS] <INPUT>\n       {} <COMMAND>\n", bin, bin)
}

fn fail_with_usage(msg: &str, usage: &str) -> Outcome {
    Outcome::Fail(format!("error: {}\n\n{}\nFor more information, try '--help'.\n", msg, usage))
}

pub fn parse(args: &[String]) -> Outcome {
    let bin = std::path::Path::new(&args[0]).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "lini".into());
    let mut opts = crate::Options { format: "svg".into(), ..Default::default() };
    let mut input: Option<String> = None;
    let mut seen: Vec<&'static str> = Vec::new(); // long names in order seen
    let mut i = 1;
    let mut only_pos = false;
    let mut want_help = false;
    let mut want_version = false;
    let used_usage = |seen: &Vec<&'static str>, extra: Option<&str>| -> String {
        let mut parts = vec![bin.clone()];
        for d in MAIN_OPTS {
            if seen.contains(&d.long) || extra == Some(d.long) {
                match d.value {
                    Some(v) => parts.push(format!("--{} <{}>", d.long, v)),
                    None => parts.push(format!("--{}", d.long)),
                }
            }
        }
        parts.push("<INPUT>".into());
        format!("Usage: {}\n", parts.join(" "))
    };
    while i < args.len() {
        let a = args[i].clone();
        i += 1;
        if !only_pos && a == "--" {
            only_pos = true;
            continue;
        }
        if !only_pos && a.starts_with("--") {
            let body = &a[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let def = match MAIN_OPTS.iter().find(|d| d.long == name) {
                Some(d) => d,
                None => {
                    let names: Vec<&str> = MAIN_OPTS.iter().map(|d| d.long).collect();
                    if let Some(s) = suggest(name, &names) {
                        let sname = MAIN_OPTS.iter().find(|d| d.long == s).unwrap().long;
                        return Outcome::Fail(format!(
                            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\nFor more information, try '--help'.\n",
                            a,
                            s,
                            used_usage(&seen, Some(sname))
                        ));
                    }
                    return Outcome::Fail(format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
                        a,
                        a,
                        a,
                        generic_usage(&bin)
                    ));
                }
            };
            if let Some(o) = handle_opt(def, inline_val, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                return o;
            }
            continue;
        }
        if !only_pos && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                let def = match MAIN_OPTS.iter().find(|d| d.short == Some(c)) {
                    Some(d) => d,
                    None => {
                        let shown = format!("-{}", c);
                        return Outcome::Fail(format!(
                            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
                            shown,
                            shown,
                            shown,
                            generic_usage(&bin)
                        ));
                    }
                };
                if def.value.is_some() {
                    let rest: String = chars[k..].iter().collect();
                    let iv = if rest.is_empty() { None } else { Some(rest) };
                    if let Some(o) = handle_opt(def, iv, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                        return o;
                    }
                    break;
                }
                if let Some(o) = handle_opt(def, None, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                    return o;
                }
                if want_help || want_version {
                    break;
                }
            }
            if want_help {
                return Outcome::Print(sub_help(&bin, HELP_MAIN));
            }
            if want_version {
                return Outcome::Print("lini 1.1.0\n".into());
            }
            continue;
        }
        // positional
        if input.is_none() && !only_pos && seen.is_empty() && SUBCOMMANDS.contains(&a.as_str()) {
            return parse_sub(&bin, &a, &args[i..]);
        }
        if input.is_none() {
            input = Some(a);
        } else {
            return fail_with_usage(&format!("the subcommand '{}' cannot be used with '<INPUT>'", a), &generic_usage(&bin));
        }
        if want_help || want_version {
            break;
        }
    }
    if want_help {
        return Outcome::Print(sub_help(&bin, HELP_MAIN));
    }
    if want_version {
        return Outcome::Print("lini 1.1.0\n".into());
    }
    if opts.no_warn && opts.strict {
        let first = if seen.iter().position(|s| *s == "no-warn") < seen.iter().position(|s| *s == "strict") { ("no-warn", "strict") } else { ("strict", "no-warn") };
        return Outcome::Fail(format!(
            "error: the argument '--{}' cannot be used with '--{}'\n\nUsage: {} --{} <INPUT>\n\nFor more information, try '--help'.\n",
            first.0, first.1, bin, first.0
        ));
    }
    let input = match input {
        Some(x) => x,
        None => {
            return Outcome::Fail(format!(
                "error: the following required arguments were not provided:\n  <INPUT>\n\n{}\nFor more information, try '--help'.\n",
                used_usage(&seen, None)
            ));
        }
    };
    if seen.contains(&"watch") && opts.output.is_none() {
        let mut s2 = seen.clone();
        s2.push("output");
        return Outcome::Fail(format!(
            "error: the following required arguments were not provided:\n  --output <OUTPUT>\n\n{}\nFor more information, try '--help'.\n",
            used_usage(&s2, None)
        ));
    }
    Outcome::Run(Parsed { cmd: Cmd::Compile { input }, opts })
}

#[allow(clippy::too_many_arguments)]
fn handle_opt(
    def: &OptDef,
    inline_val: Option<String>,
    args: &[String],
    i: &mut usize,
    opts: &mut crate::Options,
    seen: &mut Vec<&'static str>,
    want_help: &mut bool,
    want_version: &mut bool,
    bin: &str,
) -> Option<Outcome> {
    if def.long == "help" {
        *want_help = true;
        return Some(Outcome::Print(sub_help(bin, HELP_MAIN)));
    }
    if def.long == "version" {
        *want_version = true;
        return Some(Outcome::Print("lini 1.1.0\n".into()));
    }
    if seen.contains(&def.long) {
        let shown = match def.value {
            Some(v) => format!("--{} <{}>", def.long, v),
            None => format!("--{}", def.long),
        };
        return Some(fail_with_usage(&format!("the argument '{}' cannot be used multiple times", shown), &generic_usage(bin)));
    }
    seen.push(def.long);
    let val = if def.value.is_some() {
        match inline_val {
            Some(v) => Some(v),
            None => {
                if *i < args.len() {
                    let v = args[*i].clone();
                    *i += 1;
                    Some(v)
                } else {
                    return Some(Outcome::Fail(format!(
                        "error: a value is required for '--{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n",
                        def.long,
                        def.value.unwrap()
                    )));
                }
            }
        }
    } else {
        None
    };
    match def.long {
        "output" => opts.output = val,
        "format" => opts.format = val.unwrap_or_default(),
        "theme" => opts.theme = val,
        "static" => opts.static_ = true,
        "embed-font" => opts.embed_font = true,
        "check" => opts.check = true,
        "json" => opts.json = true,
        "watch" => opts.watch = true,
        "no-fs" => opts.no_fs = true,
        "no-warn" => opts.no_warn = true,
        "strict" => opts.strict = true,
        _ => {}
    }
    None
}

fn sub_usage_err(bin: &str, sub: &str, used: &[&str], required: &str) -> Outcome {
    let mut parts = vec![bin.to_string(), sub.to_string()];
    for u in used {
        parts.push(u.to_string());
    }
    parts.push(required.to_string());
    Outcome::Fail(format!(
        "error: the following required arguments were not provided:\n  {}\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        required,
        parts.join(" ")
    ))
}

fn unexpected(bin: &str, arg: &str, usage: &str) -> Outcome {
    let _ = bin;
    if arg.starts_with('-') && arg.len() > 1 {
        Outcome::Fail(format!(
            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
            arg, arg, arg, usage
        ))
    } else {
        Outcome::Fail(format!("error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n", arg, usage))
    }
}

fn parse_sub(bin: &str, sub: &str, rest: &[String]) -> Outcome {
    let opts = crate::Options { format: "svg".into(), ..Default::default() };
    match sub {
        "fmt" => {
            let usage = format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin);
            let mut check = false;
            let mut stdout = false;
            let mut used: Vec<&str> = Vec::new();
            let mut input = None;
            let mut only_pos = false;
            for a in rest {
                if !only_pos && a == "--" {
                    only_pos = true;
                    continue;
                }
                if !only_pos && (a == "-h" || a == "--help") {
                    return Outcome::Print(sub_help(bin, HELP_FMT));
                }
                if !only_pos && a == "--check" {
                    check = true;
                    used.push("--check");
                    continue;
                }
                if !only_pos && a == "--stdout" {
                    stdout = true;
                    used.push("--stdout");
                    continue;
                }
                if !only_pos && a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            match input {
                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Fmt { input, check, stdout }, opts }),
                None => sub_usage_err(bin, "fmt", &used, "<INPUT>"),
            }
        }
        "desugar" => {
            let usage = format!("Usage: {} desugar <INPUT>\n", bin);
            let mut input = None;
            // `--` ends the options: what follows is positional
            let mut only_pos = false;
            for a in rest {
                if !only_pos && a == "--" {
                    only_pos = true;
                    continue;
                }
                if !only_pos && (a == "-h" || a == "--help") {
                    return Outcome::Print(sub_help(bin, HELP_DESUGAR));
                }
                if !only_pos && a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else if only_pos {
                    return Outcome::Fail(format!(
                        "error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
                        a, usage
                    ));
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            match input {
                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Desugar { input }, opts }),
                None => sub_usage_err(bin, "desugar", &[], "<INPUT>"),
            }
        }
        "highlight" => {
            let usage = format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin);
            let mut input = None;
            let mut css = false;
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_HIGHLIGHT));
                }
                if a == "--css" {
                    css = true;
                    continue;
                }
                if a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            if !css && input.is_none() {
                return Outcome::Fail("error: an input file is required — or '--css' for the palette\n".into());
            }
            Outcome::Run(Parsed { cmd: Cmd::Highlight { input, css }, opts })
        }
        "theme" => {
            let usage = format!("Usage: {} theme [NAME]\n", bin);
            let mut name = None;
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_THEME));
                }
                if a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if name.is_none() {
                    name = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            Outcome::Run(Parsed { cmd: Cmd::Theme { name }, opts })
        }
        "serve" => {
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_SERVE));
                }
            }
            Outcome::Run(Parsed { cmd: Cmd::Serve, opts })
        }
        "help" => {
            if rest.is_empty() {
                return Outcome::Print(sub_help(bin, HELP_MAIN));
            }
            let first = rest[0].as_str();
            let text = match first {
                "fmt" => HELP_FMT,
                "serve" => HELP_SERVE,
                "desugar" => HELP_DESUGAR,
                "highlight" => HELP_HIGHLIGHT,
                "theme" => HELP_THEME,
                "help" => HELP_HELP,
                _ => {
                    return fail_with_usage(&format!("unrecognized subcommand '{}'", first), &generic_usage(bin));
                }
            };
            if rest.len() > 1 {
                let u = match first {
                    "fmt" => format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin),
                    "desugar" => format!("Usage: {} desugar <INPUT>\n", bin),
                    "highlight" => format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin),
                    "theme" => format!("Usage: {} theme [NAME]\n", bin),
                    "serve" => format!("Usage: {} serve [OPTIONS] [PATH]\n", bin),
                    _ => format!("Usage: {} help [COMMAND]...\n", bin),
                };
                return fail_with_usage(&format!("unrecognized subcommand '{}'", rest[1]), &u);
            }
            Outcome::Print(sub_help(bin, text))
        }
        _ => Outcome::Fail(String::new()),
    }
}

use clap::{Args, Parser, Subcommand, error::ErrorKind};
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::time::{Duration, Instant};

#[derive(Parser)]
#[command(
    name = "lini",
    version,
    about = "Compile Lini diagrams to SVG",
    long_about = None,
    disable_help_flag = false,
    args_conflicts_with_subcommands = true,
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Command>,

    /// The default (no-subcommand) invocation: compile a file to SVG.
    #[command(flatten)]
    compile: Option<CompileArgs>,
}

#[derive(Subcommand)]
enum Command {
    /// Reformat a file to canonical style in place
    Fmt {
        /// Input .lini file (use '-' for stdin → stdout)
        input: String,
        /// Exit 1 if reformatting would change the file. Write nothing.
        #[arg(long = "check")]
        check: bool,
        /// Print formatted output to stdout instead of rewriting.
        #[arg(long = "stdout")]
        stdout: bool,
    },
    /// Serve a live preview (a file) or the playground (a directory)
    Serve {
        /// A .lini file (live-reload preview) or a directory (playground);
        /// omitted → the current directory.
        path: Option<String>,
        /// Port to bind (default 7700).
        #[arg(long = "port", default_value_t = 7700)]
        port: u16,
        /// Bake CSS variables and outline text (for non-browser renderers).
        #[arg(long = "static")]
        static_mode: bool,
        /// A theme for every served compile: a built-in name, a CSS file of
        /// `--lini-*` overrides, or a light/dark pair. See `lini theme`.
        #[arg(long = "theme", value_name = "NAME|FILE|A/B")]
        theme: Option<String>,
    },
    /// Print a file lowered to primitives + .lini-* classes
    Desugar {
        /// Input .lini file (use '-' for stdin)
        input: String,
    },
    /// Print a file as syntax-highlighted HTML — <span class="lini-tok-*"> runs
    Highlight {
        /// Input .lini file (use '-' for stdin); omitted with --css.
        input: Option<String>,
        /// Print the token palette those spans wear, as a CSS file, instead.
        #[arg(long = "css")]
        css: bool,
    },
    /// List the built-in themes, or print one as a --lini-* CSS file
    Theme {
        /// A theme name to print; omitted → list them all.
        name: Option<String>,
    },
}

#[derive(Args)]
struct CompileArgs {
    /// Input .lini file (use '-' for stdin)
    input: String,

    /// Output path (default: stdout)
    #[arg(short = 'o', long = "output")]
    output: Option<PathBuf>,

    /// Output wrapper: `svg` (default) or `html`.
    #[arg(long = "format", default_value = "svg")]
    format: String,

    /// Inline `var()`s as literals **and** outline text to paths —
    /// self-contained for any renderer (resvg, librsvg, raster converters).
    #[arg(long = "static")]
    static_mode: bool,

    /// Embed the used bundled font family × weights as base64 `@font-face` —
    /// browser-only (resvg/librsvg ignore `@font-face`).
    #[arg(long = "embed-font")]
    embed_font: bool,

    /// Run the full compile but write nothing — every error and warning
    /// the compile would report, without the SVG.
    #[arg(long = "check")]
    check: bool,

    /// Emit diagnostics as a JSON document (stable codes, spans, and
    /// machine-applicable fixes) instead of SVG — the tooling/LSP form
    /// [SPEC 20/21]. Exit 1 if any error-level diagnostic fired.
    #[arg(long = "json")]
    json: bool,

    /// A theme: a built-in name (`dark`, `high-contrast`, …), a CSS file of `--lini-*`
    /// overrides, or a light/dark pair (`light/dark`). See `lini theme`.
    #[arg(long = "theme", value_name = "NAME|FILE|A/B")]
    theme: Option<String>,

    /// Recompile on every change to the input file. Requires `-o`.
    #[arg(long = "watch", requires = "output")]
    watch: bool,

    /// Read nothing from disk but the input: a local `|image|` path errors
    /// and `--theme` takes a built-in only. For compiling source you did not
    /// write (a rendering service).
    #[arg(long = "no-fs")]
    no_fs: bool,

    /// Suppress lint warnings.
    #[arg(long = "no-warn", conflicts_with = "strict")]
    no_warn: bool,

    /// Treat lint warnings as errors. Useful for CI.
    #[arg(long = "strict")]
    strict: bool,
}

fn main() -> ExitCode {
    let parsed = match Cli::try_parse() {
        Ok(c) => c,
        Err(e) => {
            // clap prints help/version to stdout and errors to stderr itself.
            let _ = e.print();
            return match e.kind() {
                ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => ExitCode::SUCCESS,
                _ => ExitCode::from(3),
            };
        }
    };
    let cli = match parsed.command {
        Some(Command::Fmt {
            input,
            check,
            stdout,
        }) => return run_fmt(&input, check, stdout),
        Some(Command::Serve {
            path,
            port,
            static_mode,
            theme,
        }) => return run_serve(path, port, static_mode, theme.as_deref()),
        Some(Command::Desugar { input }) => return run_desugar(&input),
        Some(Command::Highlight { input, css }) => return run_highlight(input.as_deref(), css),
        Some(Command::Theme { name }) => return run_theme(name.as_deref()),
        None => match parsed.compile {
            Some(c) => c,
            None => {
                eprintln!("error: an input file (or a subcommand) is required — see 'lini --help'");
                return ExitCode::from(3);
            }
        },
    };

    // The two font flags need the subset bytes — the default-on `font`
    // feature [SPEC 20]. Name-only output never does.
    if (cli.static_mode || cli.embed_font) && !lini::font_support() {
        eprintln!(
            "error: --static and --embed-font need the bundled fonts — rebuild with the `font` feature (on by default)"
        );
        return ExitCode::from(3);
    }

    let format = match cli.format.as_str() {
        "svg" => lini::OutputFormat::Svg,
        "html" => lini::OutputFormat::Html,
        other => {
            eprintln!("error: invalid --format '{}' (expected svg|html)", other);
            return ExitCode::from(3);
        }
    };
    // Resolve `--theme` (a built-in name, a light/dark pair, or a file) to the
    // `--lini-*` CSS the resolver layers over the defaults.
    let theme_css = match &cli.theme {
        Some(arg) => match theme_css_for(arg, !cli.no_fs) {
            Ok(css) => Some(css),
            Err(code) => return code,
        },
        None => None,
    };

    // Local image paths resolve against the source file's directory [SPEC 7];
    // stdin has none. A plain CLI compile is unbounded — no asset root [SPEC 20].
    let base_dir = (cli.input != "-")
        .then(|| Path::new(&cli.input).parent().map(Path::to_path_buf))
        .flatten();

    let opts = lini::Options {
        static_mode: cli.static_mode,
        embed_font: cli.embed_font,
        format,
        theme_css,
        base_dir,
        no_fs: cli.no_fs,
        ..Default::default()
    };
    let build = Build {
        form: if cli.json {
            Form::Json
        } else if cli.check {
            Form::Check
        } else {
            Form::Svg
        },
        output: cli.output,
        no_warn: cli.no_warn,
        strict: cli.strict,
    };

    if cli.watch {
        if cli.input == "-" {
            eprintln!("error: --watch cannot read from stdin");
            return ExitCode::from(3);
        }
        return watch_loop(Path::new(&cli.input), &opts, &build);
    }

    let (filename, source) = match cli.input.as_str() {
        "-" => {
            let mut buf = String::new();
            if let Err(e) = std::io::stdin().read_to_string(&mut buf) {
                eprintln!("error: failed to read stdin: {}", e);
                return ExitCode::from(2);
            }
            ("<stdin>".to_string(), buf)
        }
        path => match std::fs::read_to_string(path) {
            Ok(s) => (path.to_string(), s),
            Err(e) => {
                eprintln!("error: {}: {}", path, e);
                return ExitCode::from(2);
            }
        },
    };
    ExitCode::from(build.run(&source, &filename, &opts))
}

/// What a compile emits: the SVG, nothing (`--check`), or the diagnostics as
/// JSON. All three run the same passes, so they agree on what a file is worth.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Form {
    Svg,
    Check,
    Json,
}

/// One build of one source — the default invocation and each `--watch` turn.
/// The CLI contract lives here alone [SPEC 20]: an error is exit 1, a warning
/// prints (unless `--no-warn`) and is exit 1 under `--strict`, I/O is exit 2.
struct Build {
    form: Form,
    output: Option<PathBuf>,
    no_warn: bool,
    strict: bool,
}

impl Build {
    fn run(&self, source: &str, filename: &str, opts: &lini::Options) -> u8 {
        if self.form == Form::Json {
            let (doc, worst) = lini::diagnostics_json(source, opts, filename);
            print!("{}", doc);
            return self.exit_for(worst);
        }
        let result = match self.form {
            Form::Check => lini::check_with(source, opts).map(|diags| (None, diags)),
            _ => lini::compile_str_checked(source, opts).map(|(svg, diags)| (Some(svg), diags)),
        };
        let (svg, diags) = match result {
            Ok(built) => built,
            Err(e) => {
                eprintln!("{}", e.display_with_source(source, filename));
                return 1;
            }
        };
        if !self.no_warn {
            for d in &diags {
                eprintln!("{}", d.display_with_source(source, filename));
            }
        }
        if let Some(svg) = svg {
            match &self.output {
                Some(path) => {
                    if let Err(e) = std::fs::write(path, svg.as_bytes()) {
                        eprintln!("error: write {}: {}", path.display(), e);
                        return 2;
                    }
                }
                None => print!("{}", svg),
            }
        }
        self.exit_for(lini::Level::worst(&diags))
    }

    fn exit_for(&self, worst: Option<lini::Level>) -> u8 {
        match worst {
            Some(lini::Level::Error) => 1,
            Some(lini::Level::Warning) if self.strict => 1,
            _ => 0,
        }
    }
}

fn watch_loop(input: &Path, opts: &lini::Options, build: &Build) -> ExitCode {
    let output = build
        .output
        .as_deref()
        .expect("clap enforces -o with --watch");
[package]
name = "lini"
version = "1.1.0"
edition = "2024"
rust-version = "1.88"
description = "From a mindmap to a blueprint: one small language for diagrams, charts, sequences, ER schemas, engineering drawings, and schematics. Compiles to clean, themeable SVG."
license = "MIT"
repository = "https://github.com/monfa-red/lini"
homepage = "https://lini.rs"
documentation = "https://docs.rs/lini"
readme = "README.md"
keywords = ["diagram", "svg", "dsl", "diagrams-as-code", "mermaid"]
categories = ["command-line-utilities", "visualization", "development-tools"]
# Raw font sources are xtask input only (the committed subsets/metrics are the
# shipped artifacts) — keep the ~8 MB out of the published crate. The README's
# imagery is fetched from GitHub by URL, never from the package, so the crate
# carries none of it either; the PNGs stay in the repo because the READMEs of
# already-published versions still point at them.
exclude = ["assets/fonts/raw", "assets/*.png", "assets/*.svg", "assets/logo"]

[[bin]]
name = "lini"
path = "src/main.rs"

[lib]
name = "lini"
path = "src/lib.rs"

[dependencies]
clap = { version = "4.6", features = ["derive"] }
libm = "0.2"
ttf-parser = { version = "0.25", optional = true }

[features]
default = ["icons", "font"]
# Embed the Phosphor icon set (assets/phosphor-duotone.txt). On by default;
# `--no-default-features` drops it for a lean binary (then `|icon|` errors).
icons = []
# Embed the bundled font subsets (assets/fonts/subset/) for `--embed-font` /
# `--static` text outlining. On by default; the metrics tables are always
# compiled in regardless — layout never varies by build flags — so dropping
# this only loses the two font flags, never measurement.
font = ["dep:ttf-parser"]

[dev-dependencies]
insta = { version = "1.47", features = ["glob", "filters"] }

[profile.release]
lto = "thin"
codegen-units = 1
strip = "symbols"

# The browser build, used by `cargo xtask wasm`. Cargo reads profiles only from
# the workspace root, so `crates/lini-wasm` cannot carry its own — and the
# binary must not inherit these: `opt-level = "z"` trades the CLI's speed for
# bytes, a bargain that is only ever right over the network.
[profile.wasm-release]
inherits = "release"
opt-level = "z"
lto = "fat"
panic = "abort"

# `xtask` holds repo tooling (icon extraction, future font embedding);
# `crates/lini-wasm` is the browser binding, built only for wasm32 by
# `cargo xtask wasm`. Neither is part of the published crate; default-members
# keeps `cargo build/test` on lini alone, so a host-target build never tries to
# compile the cdylib.
[workspace]
members = ["xtask", "crates/lini-wasm"]
default-members = ["."]
