use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: failed to read stdin: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => String::from_utf8(b).map_err(|_| format!("error: {}: stream did not contain valid UTF-8", path)),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet, src);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    icon::validate(&b.nodes, b.sheet, file, opts).map_err(|e| (e, vec![]))?;
    b.resolve_links().map_err(|e| (e, vec![]))?;
    page::root_fixup(&mut b.nodes, b.sheet);
    b.unworn_class_warnings();
    let nodes = std::mem::take(&mut b.nodes);
    let links = std::mem::take(&mut b.links);
    let mut warnings = std::mem::take(&mut b.warnings);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links,
        warnings: std::mem::take(&mut warnings),
        root_font_size: 15.0,
        sk: Default::default(),
        link_geo: vec![],
    };
    compile::compute(&mut ctx);
    if drawing::expand(&mut ctx).map_err(|e| (e, vec![]))? {
        compile::compute(&mut ctx);
    }
    chart::validate(&ctx).map_err(|e| (e, vec![]))?;
    page::scale_units(&mut ctx);
    drawing::prepare(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    image::check_sizes(&ctx).map_err(|e| (e, vec![]))?;
    layout::measure(&mut ctx, 0, None);
    drawing::size_warnings(&mut ctx);
    links::compute(&mut ctx);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    table::check_grids(&ctx).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}
// Command-line parsing, mirroring clap's behaviour and messages.

pub static HELP_MAIN: &str = include_str!("../data/help/main.txt");
pub static HELP_FMT: &str = include_str!("../data/help/fmt.txt");
pub static HELP_SERVE: &str = include_str!("../data/help/serve.txt");
pub static HELP_DESUGAR: &str = include_str!("../data/help/desugar.txt");
pub static HELP_HIGHLIGHT: &str = include_str!("../data/help/highlight.txt");
pub static HELP_THEME: &str = include_str!("../data/help/theme.txt");
pub static HELP_HELP: &str = include_str!("../data/help/help.txt");
pub static HIGHLIGHT_CSS: &str = include_str!("../data/help/highlight.css");

pub enum Cmd {
    Compile { input: String },
    Fmt { input: String, check: bool, stdout: bool },
    Serve,
    Desugar { input: String },
    Highlight { input: Option<String>, css: bool },
    Theme { name: Option<String> },
}

pub struct Parsed {
    pub cmd: Cmd,
    pub opts: crate::Options,
}

pub enum Outcome {
    Run(Parsed),
    Print(String), // help / version text on stdout, exit 0
    Fail(String),  // error text on stderr, exit 3
}

struct OptDef {
    long: &'static str,
    short: Option<char>,
    value: Option<&'static str>, // value name when the option takes one
}

const MAIN_OPTS: &[OptDef] = &[
    OptDef { long: "output", short: Some('o'), value: Some("OUTPUT") },
    OptDef { long: "format", short: None, value: Some("FORMAT") },
    OptDef { long: "static", short: None, value: None },
    OptDef { long: "embed-font", short: None, value: None },
    OptDef { long: "check", short: None, value: None },
    OptDef { long: "json", short: None, value: None },
    OptDef { long: "theme", short: None, value: Some("NAME|FILE|A/B") },
    OptDef { long: "watch", short: None, value: None },
    OptDef { long: "no-fs", short: None, value: None },
    OptDef { long: "no-warn", short: None, value: None },
    OptDef { long: "strict", short: None, value: None },
    OptDef { long: "help", short: Some('h'), value: None },
    OptDef { long: "version", short: Some('V'), value: None },
];

const SUBCOMMANDS: &[&str] = &["fmt", "serve", "desugar", "highlight", "theme", "help"];

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut am = vec![false; a.len()];
    let mut bm = vec![false; b.len()];
    let mut m = 0usize;
    for i in 0..a.len() {
        let lo = i.saturating_sub(range);
        let hi = (i + range + 1).min(b.len());
        for j in lo..hi {
            if !bm[j] && a[i] == b[j] {
                am[i] = true;
                bm[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if am[i] {
            while !bm[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = m as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64 / 2.0) / m) / 3.0
}

fn suggest(given: &str, cands: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for c in cands {
        let s = jaro(given, c);
        if s > 0.7 && best.map(|b| s > b.0).unwrap_or(true) {
            best = Some((s, c));
        }
    }
    best.map(|b| b.1.to_string())
}

pub fn sub_help(bin: &str, text: &str) -> String {
    text.replace("{bin}", bin)
}

fn generic_usage(bin: &str) -> String {
    format!("Usage: {} [OPTIONS] <INPUT>\n       {} <COMMAND>\n", bin, bin)
}

fn fail_with_usage(msg: &str, usage: &str) -> Outcome {
    Outcome::Fail(format!("error: {}\n\n{}\nFor more information, try '--help'.\n", msg, usage))
}

pub fn parse(args: &[String]) -> Outcome {
    let bin = std::path::Path::new(&args[0]).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "lini".into());
    let mut opts = crate::Options { format: "svg".into(), ..Default::default() };
    let mut input: Option<String> = None;
    let mut seen: Vec<&'static str> = Vec::new(); // long names in order seen
    let mut i = 1;
    let mut only_pos = false;
    let mut want_help = false;
    let mut want_version = false;
    let used_usage = |seen: &Vec<&'static str>, extra: Option<&str>| -> String {
        let mut parts = vec![bin.clone()];
        for d in MAIN_OPTS {
            if seen.contains(&d.long) || extra == Some(d.long) {
                match d.value {
                    Some(v) => parts.push(format!("--{} <{}>", d.long, v)),
                    None => parts.push(format!("--{}", d.long)),
                }
            }
        }
        parts.push("<INPUT>".into());
        format!("Usage: {}\n", parts.join(" "))
    };
    while i < args.len() {
        let a = args[i].clone();
        i += 1;
        if !only_pos && a == "--" {
            only_pos = true;
            continue;
        }
        if !only_pos && a.starts_with("--") {
            let body = &a[2..];
            let (name, inline_val) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            let def = match MAIN_OPTS.iter().find(|d| d.long == name) {
                Some(d) => d,
                None => {
                    let names: Vec<&str> = MAIN_OPTS.iter().map(|d| d.long).collect();
                    if let Some(s) = suggest(name, &names) {
                        let sname = MAIN_OPTS.iter().find(|d| d.long == s).unwrap().long;
                        return Outcome::Fail(format!(
                            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\nFor more information, try '--help'.\n",
                            a,
                            s,
                            used_usage(&seen, Some(sname))
                        ));
                    }
                    return Outcome::Fail(format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
                        a,
                        a,
                        a,
                        generic_usage(&bin)
                    ));
                }
            };
            if let Some(o) = handle_opt(def, inline_val, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                return o;
            }
            continue;
        }
        if !only_pos && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                let def = match MAIN_OPTS.iter().find(|d| d.short == Some(c)) {
                    Some(d) => d,
                    None => {
                        let shown = format!("-{}", c);
                        return Outcome::Fail(format!(
                            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
                            shown,
                            shown,
                            shown,
                            generic_usage(&bin)
                        ));
                    }
                };
                if def.value.is_some() {
                    let rest: String = chars[k..].iter().collect();
                    let iv = if rest.is_empty() { None } else { Some(rest) };
                    if let Some(o) = handle_opt(def, iv, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                        return o;
                    }
                    break;
                }
                if let Some(o) = handle_opt(def, None, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
                    return o;
                }
                if want_help || want_version {
                    break;
                }
            }
            if want_help {
                return Outcome::Print(sub_help(&bin, HELP_MAIN));
            }
            if want_version {
                return Outcome::Print("lini 1.1.0\n".into());
            }
            continue;
        }
        // positional
        if input.is_none() && !only_pos && seen.is_empty() && SUBCOMMANDS.contains(&a.as_str()) {
            return parse_sub(&bin, &a, &args[i..]);
        }
        if input.is_none() {
            input = Some(a);
        } else {
            return fail_with_usage(&format!("the subcommand '{}' cannot be used with '<INPUT>'", a), &generic_usage(&bin));
        }
        if want_help || want_version {
            break;
        }
    }
    if want_help {
        return Outcome::Print(sub_help(&bin, HELP_MAIN));
    }
    if want_version {
        return Outcome::Print("lini 1.1.0\n".into());
    }
    if opts.no_warn && opts.strict {
        let first = if seen.iter().position(|s| *s == "no-warn") < seen.iter().position(|s| *s == "strict") { ("no-warn", "strict") } else { ("strict", "no-warn") };
        return Outcome::Fail(format!(
            "error: the argument '--{}' cannot be used with '--{}'\n\nUsage: {} --{} <INPUT>\n\nFor more information, try '--help'.\n",
            first.0, first.1, bin, first.0
        ));
    }
    let input = match input {
        Some(x) => x,
        None => {
            return Outcome::Fail(format!(
                "error: the following required arguments were not provided:\n  <INPUT>\n\n{}\nFor more information, try '--help'.\n",
                used_usage(&seen, None)
            ));
        }
    };
    if seen.contains(&"watch") && opts.output.is_none() {
        let mut s2 = seen.clone();
        s2.push("output");
        return Outcome::Fail(format!(
            "error: the following required arguments were not provided:\n  --output <OUTPUT>\n\n{}\nFor more information, try '--help'.\n",
            used_usage(&s2, None)
        ));
    }
    Outcome::Run(Parsed { cmd: Cmd::Compile { input }, opts })
}
