) -> Option<Outcome> {
    if def.long == "help" {
        *want_help = true;
        return Some(Outcome::Print(sub_help(bin, HELP_MAIN)));
    }
    if def.long == "version" {
        *want_version = true;
        return Some(Outcome::Print("lini 1.1.0\n".into()));
    }
    if seen.contains(&def.long) {
        let shown = match def.value {
            Some(v) => format!("--{} <{}>", def.long, v),
            None => format!("--{}", def.long),
        };
        return Some(fail_with_usage(&format!("the argument '{}' cannot be used multiple times", shown), &generic_usage(bin)));
    }
    seen.push(def.long);
    let val = if def.value.is_some() {
        match inline_val {
            Some(v) => Some(v),
            None => {
                if *i < args.len() {
                    let v = args[*i].clone();
                    *i += 1;
                    Some(v)
                } else {
                    return Some(Outcome::Fail(format!(
                        "error: a value is required for '--{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n",
                        def.long,
                        def.value.unwrap()
                    )));
                }
            }
        }
    } else {
        None
    };
    match def.long {
        "output" => opts.output = val,
        "format" => opts.format = val.unwrap_or_default(),
        "theme" => opts.theme = val,
        "static" => opts.static_ = true,
        "embed-font" => opts.embed_font = true,
        "check" => opts.check = true,
        "json" => opts.json = true,
        "watch" => opts.watch = true,
        "no-fs" => opts.no_fs = true,
        "no-warn" => opts.no_warn = true,
        "strict" => opts.strict = true,
        _ => {}
    }
    None
}

fn sub_usage_err(bin: &str, sub: &str, used: &[&str], required: &str) -> Outcome {
    let mut parts = vec![bin.to_string(), sub.to_string()];
    for u in used {
        parts.push(u.to_string());
    }
    parts.push(required.to_string());
    Outcome::Fail(format!(
        "error: the following required arguments were not provided:\n  {}\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        required,
        parts.join(" ")
    ))
}

fn unexpected(bin: &str, arg: &str, usage: &str) -> Outcome {
    let _ = bin;
    if arg.starts_with('-') && arg.len() > 1 {
        Outcome::Fail(format!(
            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
            arg, arg, arg, usage
        ))
    } else {
        Outcome::Fail(format!("error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n", arg, usage))
    }
}

fn parse_sub(bin: &str, sub: &str, rest: &[String]) -> Outcome {
    let opts = crate::Options { format: "svg".into(), ..Default::default() };
    match sub {
        "fmt" => {
            let usage = format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin);
            let mut check = false;
            let mut stdout = false;
            let mut used: Vec<&str> = Vec::new();
            let mut input = None;
            let mut only_pos = false;
            for a in rest {
                if !only_pos && a == "--" {
                    only_pos = true;
                    continue;
                }
                if !only_pos && (a == "-h" || a == "--help") {
                    return Outcome::Print(sub_help(bin, HELP_FMT));
                }
                if !only_pos && a == "--check" {
                    check = true;
                    used.push("--check");
                    continue;
                }
                if !only_pos && a == "--stdout" {
                    stdout = true;
                    used.push("--stdout");
                    continue;
                }
                if !only_pos && a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            match input {
                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Fmt { input, check, stdout }, opts }),
                None => sub_usage_err(bin, "fmt", &used, "<INPUT>"),
            }
        }
        "desugar" => {
            let usage = format!("Usage: {} desugar <INPUT>\n", bin);
            let mut input = None;
            // `--` ends the options: what follows is positional
            let mut only_pos = false;
            for a in rest {
                if !only_pos && a == "--" {
                    only_pos = true;
                    continue;
                }
                if !only_pos && (a == "-h" || a == "--help") {
                    return Outcome::Print(sub_help(bin, HELP_DESUGAR));
                }
                if !only_pos && a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else if only_pos {
                    return Outcome::Fail(format!(
                        "error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
                        a, usage
                    ));
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            match input {
                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Desugar { input }, opts }),
                None => sub_usage_err(bin, "desugar", &[], "<INPUT>"),
            }
        }
        "highlight" => {
            let usage = format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin);
            let mut input = None;
            let mut css = false;
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_HIGHLIGHT));
                }
                if a == "--css" {
                    css = true;
                    continue;
                }
                if a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if input.is_none() {
                    input = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            if !css && input.is_none() {
                return Outcome::Fail("error: an input file is required — or '--css' for the palette\n".into());
            }
            Outcome::Run(Parsed { cmd: Cmd::Highlight { input, css }, opts })
        }
        "theme" => {
            let usage = format!("Usage: {} theme [NAME]\n", bin);
            let mut name = None;
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_THEME));
                }
                if a.starts_with('-') && a != "-" {
                    return unexpected(bin, a, &usage);
                }
                if name.is_none() {
                    name = Some(a.clone());
                } else {
                    return unexpected(bin, a, &usage);
                }
            }
            Outcome::Run(Parsed { cmd: Cmd::Theme { name }, opts })
        }
        "serve" => {
            for a in rest {
                if a == "-h" || a == "--help" {
                    return Outcome::Print(sub_help(bin, HELP_SERVE));
                }
            }
            Outcome::Run(Parsed { cmd: Cmd::Serve, opts })
        }
        "help" => {
            if rest.is_empty() {
                return Outcome::Print(sub_help(bin, HELP_MAIN));
            }
            let first = rest[0].as_str();
            let text = match first {
                "fmt" => HELP_FMT,
                "serve" => HELP_SERVE,
                "desugar" => HELP_DESUGAR,
                "highlight" => HELP_HIGHLIGHT,
                "theme" => HELP_THEME,
                "help" => HELP_HELP,
                _ => {
                    return fail_with_usage(&format!("unrecognized subcommand '{}'", first), &generic_usage(bin));
                }
            };
            if rest.len() > 1 {
                let u = match first {
                    "fmt" => format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin),
                    "desugar" => format!("Usage: {} desugar <INPUT>\n", bin),
                    "highlight" => format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin),
                    "theme" => format!("Usage: {} theme [NAME]\n", bin),
                    "serve" => format!("Usage: {} serve [OPTIONS] [PATH]\n", bin),
                    _ => format!("Usage: {} help [COMMAND]...\n", bin),
                };
                return fail_with_usage(&format!("unrecognized subcommand '{}'", rest[1]), &u);
            }
            Outcome::Print(sub_help(bin, text))
        }
        _ => Outcome::Fail(String::new()),
    }
}
// Built-in themes: the palette as `--lini-*` custom properties.

use std::collections::HashMap;

pub static DEFAULT_CSS: &str = include_str!("../data/themes/default.css");
pub static LIGHT_CSS: &str = include_str!("../data/themes/light.css");
pub static DARK_CSS: &str = include_str!("../data/themes/dark.css");
pub static HC_CSS: &str = include_str!("../data/themes/high-contrast.css");
pub static BLUEPRINT_CSS: &str = include_str!("../data/themes/blueprint.css");
pub static LIST: &str = include_str!("../data/themes/list.txt");

pub const FONT_FAMILY: &str =
    "\"Google Sans\", system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif";

pub const NAMES: &[&str] = &["default", "light", "dark", "high-contrast", "blueprint"];

pub fn css_of(name: &str) -> Option<&'static str> {
    match name {
        "default" => Some(DEFAULT_CSS),
        "light" => Some(LIGHT_CSS),
        "dark" => Some(DARK_CSS),
        "high-contrast" => Some(HC_CSS),
        "blueprint" => Some(BLUEPRINT_CSS),
        _ => None,
    }
}

// Split "light-dark(a, b)" at its top-level comma.
pub fn split_light_dark(v: &str) -> Option<(String, String)> {
    let inner = v.strip_prefix("light-dark(")?.strip_suffix(')')?;
    let mut depth = 0;
    for (i, c) in inner.char_indices() {
        match c {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                return Some((inner[..i].trim().to_string(), inner[i + 1..].trim().to_string()));
            }
            _ => {}
        }
    }
    None
}

#[derive(Clone, Debug)]
pub struct Theme {
    pub pair: bool,
    // var name (without --lini-) → (light, dark)
    pub vars: HashMap<String, (String, String)>,
}

pub fn parse_theme_css(css: &str) -> HashMap<String, (String, String)> {
    let mut m = HashMap::new();
    for line in css.lines() {
        let l = line.trim();
        if let Some(rest) = l.strip_prefix("--lini-") {
            if let Some(colon) = rest.find(':') {
                let name = rest[..colon].to_string();
                let val = rest[colon + 1..].trim().trim_end_matches(';').trim().to_string();
                let pair = split_light_dark(&val).unwrap_or((val.clone(), val.clone()));
                m.insert(name, pair);
            }
        }
    }
    m.insert("font-family".to_string(), (FONT_FAMILY.to_string(), FONT_FAMILY.to_string()));
    m
}

pub fn builtin(name: &str) -> Option<Theme> {
    let css = css_of(name)?;
    let pair = name == "default" || name == "high-contrast";
    Some(Theme { pair, vars: parse_theme_css(css) })
}

pub fn resolve(spec: &str) -> Option<Theme> {
    if let Some((a, b)) = spec.split_once('/') {
        let ta = builtin(a)?;
        let tb = builtin(b)?;
        let mut vars = HashMap::new();
        for (k, (l, _)) in &ta.vars {
            let d = tb.vars.get(k).map(|x| x.1.clone()).unwrap_or_else(|| l.clone());
            vars.insert(k.clone(), (l.clone(), d));
        }
        return Some(Theme { pair: true, vars });
    }
    builtin(spec)
}

impl Theme {
    pub fn css_value(&self, var: &str) -> Option<String> {
        let (l, d) = self.vars.get(var)?;
        if !self.pair || l == d {
            if !self.pair {
                return Some(l.clone());
            }
            return Some(l.clone());
        }
        Some(format!("light-dark({}, {})", l, d))
    }
    // the light-side literal value (for --static baking)
    pub fn light_value(&self, var: &str) -> Option<String> {
        self.vars.get(var).map(|x| x.0.clone())
    }
}
// Bundled font metrics and outlines (TrueType, parsed at first use).

use std::collections::HashMap;
use std::sync::OnceLock;

pub static SANS_400: &[u8] = include_bytes!("../fonts/sans-400.ttf");
pub static SANS_500: &[u8] = include_bytes!("../fonts/sans-500.ttf");
pub static SANS_600: &[u8] = include_bytes!("../fonts/sans-600.ttf");
pub static SANS_700: &[u8] = include_bytes!("../fonts/sans-700.ttf");
pub static CODE_400: &[u8] = include_bytes!("../fonts/code-400.ttf");
pub static CODE_500: &[u8] = include_bytes!("../fonts/code-500.ttf");
pub static CODE_600: &[u8] = include_bytes!("../fonts/code-600.ttf");
pub static CODE_700: &[u8] = include_bytes!("../fonts/code-700.ttf");

pub struct Font {
    pub data: &'static [u8],
    pub upem: f64,
    pub cmap: HashMap<u32, u16>,
    pub adv: Vec<u16>,
    pub loca: Vec<u32>,
    pub glyf_off: usize,
    pub ascent: i16,
    pub descent: i16,
}

fn rd16(d: &[u8], o: usize) -> u16 {
    u16::from_be_bytes([d[o], d[o + 1]])
}
fn rd32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

impl Font {
    fn parse(data: &'static [u8]) -> Font {
        let n = rd16(data, 4) as usize;
        let mut tables: HashMap<String, (usize, usize)> = HashMap::new();
        for i in 0..n {
            let o = 12 + 16 * i;
            let tag = String::from_utf8_lossy(&data[o..o + 4]).to_string();
            tables.insert(tag, (rd32(data, o + 8) as usize, rd32(data, o + 12) as usize));
        }
        let head = tables["head"].0;
        let upem = rd16(data, head + 18) as f64;
        let index_to_loc = rd16(data, head + 50) as i16;
        let hhea = tables["hhea"].0;
        let ascent = rd16(data, hhea + 4) as i16;
        let descent = rd16(data, hhea + 6) as i16;
        let nhm = rd16(data, hhea + 34) as usize;
        let maxp = tables["maxp"].0;
        let ng = rd16(data, maxp + 4) as usize;
        let hmtx = tables["hmtx"].0;
        let mut adv = Vec::with_capacity(ng);
        for i in 0..ng {
            if i < nhm {
                adv.push(rd16(data, hmtx + 4 * i));
            } else {
                let last = *adv.last().unwrap_or(&0);
                adv.push(last);
            }
        }
        let mut cmap = HashMap::new();
        let cm = tables["cmap"].0;
        let nt = rd16(data, cm + 2) as usize;
        for i in 0..nt {
            let so = cm + rd32(data, cm + 4 + 8 * i + 4) as usize;
            let fmt = rd16(data, so);
            if fmt == 12 {
                let ngr = rd32(data, so + 12) as usize;
                for j in 0..ngr {
                    let a = rd32(data, so + 16 + 12 * j);
                    let b = rd32(data, so + 20 + 12 * j);
                    let g = rd32(data, so + 24 + 12 * j);
                    for c in a..=b {
                        cmap.insert(c, (g + (c - a)) as u16);
                    }
                }
            } else if fmt == 4 {
                let segx2 = rd16(data, so + 6) as usize;
                let seg = segx2 / 2;
                for k in 0..seg {
                    let end = rd16(data, so + 14 + 2 * k) as u32;
                    let start = rd16(data, so + 16 + segx2 + 2 * k) as u32;
                    let delta = rd16(data, so + 16 + 2 * segx2 + 2 * k) as i16 as i32;
                    let roff_pos = so + 16 + 3 * segx2 + 2 * k;
                    let roff = rd16(data, roff_pos) as usize;
                    for c in start..=end {
                        if c == 0xffff {
                            continue;
                        }
                        let g = if roff == 0 {
                            ((c as i32 + delta) & 0xffff) as u16
                        } else {
                            let p = roff_pos + roff + 2 * (c - start) as usize;
                            let g = rd16(data, p);
                            if g != 0 {
                                ((g as i32 + delta) & 0xffff) as u16
                            } else {
                                0
                            }
                        };
                        cmap.entry(c).or_insert(g);
                    }
                }
            }
        }
        let mut loca = Vec::with_capacity(ng + 1);
        if let Some(&(lo, _)) = tables.get("loca") {
            for i in 0..=ng {
                if index_to_loc == 0 {
                    loca.push(rd16(data, lo + 2 * i) as u32 * 2);
                } else {
                    loca.push(rd32(data, lo + 4 * i));
                }
            }
        }
        let glyf_off = tables.get("glyf").map(|x| x.0).unwrap_or(0);
        Font { data, upem, cmap, adv, loca, glyf_off, ascent, descent }
