p=json.load(open('/logs/agent/trajectory.json'))
rx=re.compile(r'\bevaluat(?:or|ion)\b|\bscor(?:e|ed|ing)\b|\bgrading\b|\bjudge\b', re.I)
for s in p['steps']:
 if s['source']!='agent': continue
 parts=[]
 if s.get('message'): parts.append(('message',str(s['message'])))
 for t in s.get('tool_calls',[]):
