use std::collections::HashMap;

// CSS properties in the order they are serialised.
pub const CSS_ORDER: &[&str] = &[
    "fill",
    "stroke",
    "stroke-width",
    "opacity",
    "color",
    "font-family",
    "font-size",
    "font-weight",
    "font-style",
    "text-decoration",
    "text-shadow",
    "stroke-style",
];

pub const INHERITED: &[&str] = &[
    "font-size",
