// `lini desugar`: the document lowered to primitives and `.lini-*` classes.
//
//   syntax.rs    a structural reading over the formatter's tokens, values in
//                canonical text
//   lower.rs     nodes onto primitives, labels, define bodies, links
//   sheet.rs     the stylesheet: root config, `.lini-*` rules, user rules
//   registry.rs  rule order and the internal classes' default text
//   out.rs       the desugared tree and its printer (fmt's layout rules)
//   table.rs …   the families' lowering

mod drawing;
mod lower;
mod out;
mod page;
mod registry;
mod sch_geo;
mod schematic;
mod sheet;
mod syntax;
mod table;
mod tree;

use crate::diag::Diag;

// built-in contextual rules, in the order they are written
pub static CTX_RULES: &[(&str, &str)] = &[
    (".lini-sequence .lini-note", "padding: 6 10; font-size: 13;"),
    (".lini-drawing .lini-note", "padding: 6 10; font-size: 13;"),
    (".lini-mindmap .lini-topic", "max-width: 160; font-weight: medium;"),
];

// The passes run in the original's order, so that of several errors the
// same one is reported: `|link|` nodes, the define table, the trees (a dry
// run of the lowering), the selectors, the lowering itself (a schematic
// scope checks every wire's operators on entry and resolves its endpoints
// after its content), the density, and the units last.
pub fn desugar(src: &str) -> Result<String, Diag> {
    crate::format::syntax_check(src)?;
    let doc = syntax::parse(src)?;
    let defines: Vec<syntax::Define> = doc
        .sheet
        .iter()
        .filter_map(|(it, _)| match it {
            syntax::SItem::Define(d) => Some(d.clone()),
            _ => None,
        })
        .collect();
    lower::link_check(&defines, &doc.stmts)?;
    let mut cx = lower::Cx::new(src, defines.clone());
    sheet::check_defines(&cx)?;
    {
        let mut tc = lower::Cx::new(src, defines);
        tc.tree_check = true;
        setup(&mut tc, &doc)?;
        let mut items = Vec::new();
        tc.stmts(&doc.stmts, &mut items)?;
    }
    setup(&mut cx, &doc)?;
    sheet::check_selectors(&cx, &doc.sheet)?;
    if cx.root_layout == "schematic" {
        cx.sch_ops(&doc.stmts)?;
        let plan = cx.sch_plan(&doc.stmts, true, 0)?;
        cx.root_sch = Some(plan);
    }
    let mut items = Vec::new();
    cx.stmts(&doc.stmts, &mut items)?;
    if let Some((_, e)) = cx.root_sch.as_ref().and_then(|p| p.error.clone()) {
        return Err(e);
    }
    if let Some(e) = cx.density_err.take() {
        return Err(e);
    }
    if let Some(e) = cx.unit_err.take() {
        return Err(e);
    }
    let items = cx.resolve(items);
    let sheet = sheet::build(&cx, &doc.sheet)?;
    let mut p = out::Printer::new();
    p.doc(&sheet, &items);
    Ok(p.finish())
}

// the root's config: layout, unit, density, and the scene as a tree
fn setup(cx: &mut lower::Cx, doc: &syntax::Doc) -> Result<(), Diag> {
    if let Some(l) = sheet::root_layout(&doc.sheet) {
        cx.root_layout = l;
    }
    for (it, _) in &doc.sheet {
        if let syntax::SItem::Decl(d) = it {
            if d.name == "unit" {
                cx.root_unit = d.first().map(|s| s.to_string());
            }
            if d.name == "thickness" {
                cx.root_thickness = lower::thickness_of(d);
            }
            if d.name == "density" {
                match d.first().and_then(|s| s.parse::<f64>().ok()) {
                    Some(v) if v > 0.0 => cx.density = v,
                    _ => {
                        if cx.density_err.is_none() {
                            cx.density_err = Some(Diag::error("value", "'density' must be > 0", d.span));
                        }
                    }
                }
            }
        }
    }
    // the root's unit is checked before any node's
    let unit = doc.sheet.iter().rev().find_map(|(it, _)| match it {
        syntax::SItem::Decl(d) if d.name == "unit" => Some(d),
        _ => None,
    });
    if let Some(d) = unit {
        if !sheet::unit_ok(d) {
            cx.unit_err = Some(lower::err("'unit' is px, mm, cm, m, or in", d.span));
        }
    }
    // a scene of sheets alone sits flush
    cx.root_pages = !doc.stmts.is_empty()
        && doc.stmts.iter().all(|s| match s {
            syntax::Stmt::Node(n) => {
                let ty = n.ty.clone().unwrap_or_else(|| "box".to_string());
                cx.chain(&ty).map_or(false, |(_, c)| c.iter().any(|t| t == "page"))
            }
            _ => false,
        });
    if cx.root_layout == "sequence" {
        cx.mark("line");
        cx.mark("block");
    }
    // the scene as a tree: `layout: tree`, or mindmaps at the top
    if cx.root_layout == "tree" {
        let d = doc.sheet.iter().rev().find_map(|(it, _)| match it {
            syntax::SItem::Decl(d) if d.name == "direction" => d.first().map(|s| s.to_string()),
            _ => None,
        });
        // mindmaps in the tree bring their direction and routing
        let mindmaps = tree::has_mindmap(cx, &doc.stmts);
        tree::check_roots(cx, &doc.stmts, crate::diag::Span::new(0, 0))?;
        let hoisted = mindmaps && d.is_none();
        let dir = if hoisted {
            match tree::mindmap_dir(cx, &doc.stmts) {
                Some((d, sp)) => tree::read_dir(cx, Some(d), sp)?,
                None => "bilateral".to_string(),
            }
        } else {
            tree::read_dir(cx, d, crate::diag::Span::new(0, 0))?
        };
        if mindmaps {
            cx.root_mindmap = true;
            cx.root_mindmap_dir = dir.clone();
        }
        let sem = if hoisted { "column".to_string() } else { dir.clone() };
        cx.root_tree = Some(tree::TreeMode { mindmap: false, dir, level: 0, side: None, hue: None, hoisted, sem });
    } else if !doc.sheet.iter().any(|(it, _)| matches!(it, syntax::SItem::Decl(d) if d.name == "layout"))
        && doc.stmts.iter().any(|s| matches!(s, syntax::Stmt::Node(n) if tree::is_mindmap(cx, n)))
    {
        cx.root_layout = "tree".to_string();
        cx.root_mindmap = true;
        let own_dir = doc.sheet.iter().rev().find_map(|(it, _)| match it {
            syntax::SItem::Decl(d) if d.name == "direction" => d.first().map(|s| s.to_string()),
            _ => None,
        });
        let hoisted = own_dir.is_none();
        let dir = match own_dir {
            // the scene's own direction lays out, unchecked
            Some(d) => d,
            None => match tree::mindmap_dir(cx, &doc.stmts) {
                Some((d, sp)) => tree::read_dir(cx, Some(d), sp)?,
                None => "bilateral".to_string(),
            },
        };
        cx.root_mindmap_dir = dir.clone();
        cx.root_tree =
            Some(tree::TreeMode { mindmap: true, dir, level: 0, side: None, hue: None, hoisted, sem: "bilateral".to_string() });
    }
    Ok(())
}
// `lini fmt`: reprint a document in canonical style.
//
// The formatter has its own lexer and parser (src/format/) that keep source
// positions, comments and blank lines; they follow the reference grammar and
// report the same first syntax error, which `parser::parse` reuses too.
//
//   lex.rs    tokens, each carrying the comments/blank lines in front of it
//   parse.rs  recursive descent into the concrete tree (cst.rs), errors
//   expr.rs   the math-expression reading of binding right-hand sides
//   print.rs  layout: 80 columns, 2-space indent, rows, runs, wrapping

mod cst;
pub(crate) mod expr;
pub(crate) mod lex;
pub(crate) mod parse;
mod print;

use crate::diag::Diag;

// The first syntax error, exactly as the reference compiler reports it (its
// `fmt` and compile commands share one parser). Ok(()) for a well-formed file.
pub fn syntax_check(src: &str) -> Result<(), Diag> {
    let lexed = lex::lex(src)?;
    let mut p = parse::Parser::new(src, &lexed.toks);
    p.parse_doc()?;
    Ok(())
}

pub fn format(src: &str) -> Result<String, Diag> {
    let lexed = lex::lex(src)?;
    let mut p = parse::Parser::new(src, &lexed.toks);
    let doc = p.parse_doc()?;
    let mut out = print::Out::new();
    out.doc(&doc);
    Ok(out.finish())
}
//! The `(…)` expression sub-language [SPEC 10.7] — a small, total compile-time
//! calculator: a Pratt parser and a tree-walk evaluator. It is the **only** place
//! operators live: the main parser captures a parenthesized region raw (its outer
//! parens stripped) and hands the body here to be re-lexed and folded.
//!
//! Values are numbers and points (`(x, y)`, for geometry) — no strings, no loops.
//! A body is `{ name = expr ; }* expr [ , expr ]`: leading `name = expr;` bindings are
//! locals (whole-body scope), the final expression is the value, and a top-level `,`
//! makes it a point. Functions defined in the stylesheet ([`FuncTable`]) are called by
//! name; the math library, `pi` / `e`, and the ambient sample parameter `u` are built in.
//!
//! Tokens come from the main [`crate::lexer`] in expression mode ([`lexer::lex_expr`]):
//! there is no second lexer — the parser below is a Pratt parser over that one stream.

use crate::lexer::{self, TokKind, Token};
use crate::math;
use std::collections::HashMap;

/// A folded expression value [SPEC 10.7]: a number, or a point for geometry.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Value {
    Number(f64),
    Point(f64, f64),
}

/// An expression error, message-only; the caller attaches the source span.
#[derive(Debug, Clone)]
pub struct ExprError(pub String);

impl ExprError {
    fn new(msg: impl Into<String>) -> Self {
        Self(msg.into())
    }
}

/// The ambient environment for an evaluation — the names available besides
/// locals, params, and the built-in constants. Geometry sampling injects `u`;
/// charts will inject `x` the same way.
pub type Env = HashMap<String, Value>;

// ─────────────────────────── AST ───────────────────────────

/// A parsed expression body: leading local bindings, then the value expression.
#[derive(Debug, Clone, PartialEq)]
pub struct Expr {
    locals: Vec<(String, Node)>,
    value: Node,
}

#[derive(Debug, Clone, PartialEq)]
enum Node {
    Num(f64),
    /// A bare name — a local, a param, an ambient (`u`), a constant (`pi` / `e`),
    /// or a zero-arg function.
    Var(String),
    Neg(Box<Node>),
    Bin(BinOp, Box<Node>, Box<Node>),
    Ternary(Box<Node>, Box<Node>, Box<Node>),
    Call(String, Vec<Node>),
    Point(Box<Node>, Box<Node>),
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Pow,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

/// Binding power of an infix operator (higher binds tighter). `^` is handled in
/// `parse_power`, not here, so it is absent.
fn binop_bp(op: BinOp) -> u8 {
    match op {
        BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => 1,
        BinOp::Add | BinOp::Sub => 2,
        BinOp::Mul | BinOp::Div => 3,
        BinOp::Pow => 4,
    }
}

// ─────────────────────────── Parser ───────────────────────────

/// A Pratt parser over the main lexer's tokens (in expression mode). It never
/// lexes — [`lex_expr`] already produced the stream; `src` backs the one
/// unexpected-token message so no token-printer is needed.
struct Parser<'a> {
    src: &'a str,
    toks: Vec<Token>,
    pos: usize,
}

impl Parser<'_> {
    fn kind(&self) -> Option<&TokKind> {
        self.toks.get(self.pos).map(|t| &t.kind)
    }

    fn kind_at(&self, n: usize) -> Option<&TokKind> {
        self.toks.get(self.pos + n).map(|t| &t.kind)
    }

    fn eat(&mut self, k: &TokKind) -> bool {
        if self.kind() == Some(k) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    /// `{ name = expr ; }* expr` — locals bind in order, the final expr is the value.
    fn parse_body(&mut self) -> Result<Expr, ExprError> {
        let mut locals = Vec::new();
        while matches!(self.kind(), Some(TokKind::Ident(_)))
            && matches!(self.kind_at(1), Some(TokKind::Assign))
        {
            let name = match self.kind() {
                Some(TokKind::Ident(s)) => s.clone(),
                _ => unreachable!(),
            };
            self.pos += 2; // ident '='
            let val = self.parse_ternary()?;
            if !self.eat(&TokKind::Semi) {
                return Err(ExprError::new("a local binding ends with ';'"));
            }
            locals.push((name, val));
        }
        let mut value = self.parse_ternary()?;
        // A top-level `,` makes the value a point `(x, y)` — the group's own parens
        // are stripped before it reaches here, so the comma is the point [SPEC 10.7].
        if self.eat(&TokKind::Comma) {
            let second = self.parse_ternary()?;
            value = Node::Point(Box::new(value), Box::new(second));
        }
        if self.pos != self.toks.len() {
            return Err(ExprError::new("trailing tokens after the expression"));
        }
        Ok(Expr { locals, value })
    }

    fn parse_ternary(&mut self) -> Result<Node, ExprError> {
        let cond = self.parse_binary(0)?;
        if self.eat(&TokKind::Question) {
            let a = self.parse_ternary()?;
            if !self.eat(&TokKind::Colon) {
                return Err(ExprError::new("a ternary 'cond ? a : b' needs ':'"));
            }
            let b = self.parse_ternary()?;
            Ok(Node::Ternary(Box::new(cond), Box::new(a), Box::new(b)))
        } else {
            Ok(cond)
        }
    }

    fn parse_binary(&mut self, min_bp: u8) -> Result<Node, ExprError> {
        let mut left = self.parse_unary()?;
        while let Some(op) = self.peek_binop() {
            let bp = binop_bp(op);
            if bp < min_bp {
                break;
            }
            self.pos += 1;
            let right = self.parse_binary(bp + 1)?; // all left-associative
            left = Node::Bin(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    /// The infix operators handled by `parse_binary` — `^` is right-associative
    /// and binds tighter than unary `-`, so it lives in `parse_power`.
    fn peek_binop(&self) -> Option<BinOp> {
        Some(match self.kind()? {
            TokKind::Plus => BinOp::Add,
            TokKind::Minus => BinOp::Sub,
            TokKind::Star => BinOp::Mul,
            TokKind::Slash => BinOp::Div,
            TokKind::EqEq => BinOp::Eq,
            TokKind::Ne => BinOp::Ne,
            TokKind::Lt => BinOp::Lt,
            TokKind::Le => BinOp::Le,
            TokKind::Gt => BinOp::Gt,
            TokKind::Ge => BinOp::Ge,
            _ => return None,
        })
    }

    fn parse_unary(&mut self) -> Result<Node, ExprError> {
        if self.eat(&TokKind::Minus) {
            Ok(Node::Neg(Box::new(self.parse_unary()?)))
        } else {
            self.parse_power()
        }
    }

